export class YamxError extends Error {
  constructor(code, line, message) {
    super(`${code} line ${line}: ${message}`);
    this.code = code;
    this.line = line;
  }
}

const textFail = (code, line, message) => { throw new YamxError(code, line, message); };

// Shared by the CLI's YAML input and its deliberately restricted TSV transport.
export function checkText(text, allowTab = false) {
  if (typeof text !== 'string') throw new TypeError('expected a string');
  if (text.length === 0) textFail('E_EMPTY', 1, 'expected at least one entry');
  let line = 1;
  for (const char of text) {
    const code = char.codePointAt(0);
    if (char === '\n') line++;
    else if (!(code >= 32 && code <= 126) && !(allowTab && char === '\t'))
      textFail('E_CHARACTER', line, 'unsupported byte');
  }
  if (!text.endsWith('\n')) textFail('E_NEWLINE', line, 'expected a final LF');
}

// JSON export from checked preorder nodes {depth, kind, key, value}. Keys are
// identifiers and strings are printable ASCII, so only quotes and backslashes
// need escaping. Each node emits one line; bounded depth keeps closings cheap.
const jsonString = text => `"${text.replace(/["\\]/g, '\\$&')}"`;
export function nodesJSON(nodes) {
  const lines = [];
  const open = [];
  for (let i = 0; i < nodes.length; i++) {
    const { depth, kind, key, value } = nodes[i];
    const next = i + 1 < nodes.length ? nodes[i + 1].depth : 0;
    const container = kind === 'map' || kind === 'seq';
    const children = container && next > depth;
    const scalar = kind === 'map' ? (children ? '{' : '{}') : kind === 'seq' ? (children ? '[' : '[]')
      : kind === 'str' ? jsonString(value) : kind === 'null' ? 'null' : value;
    let line = '  '.repeat(depth) + (key ? `${jsonString(key)}: ` : '') + scalar;
    if (children) { open[depth] = kind; lines.push(line); continue; }
    for (let d = depth - 1; d >= next; d--) {
      lines.push(line);
      line = '  '.repeat(d) + (open[d] === 'map' ? '}' : ']');
    }
    lines.push(i + 1 < nodes.length ? `${line},` : line);
  }
  return lines.join('\n') + '\n';
}

// YAM(M) pair-list interface; no other profile implementation is loaded.

const fail = (code, line, message) => { throw new YamxError(code, line, message); };
const keyPattern = /^[a-z_][a-z0-9_-]*$/;
const reserved = new Set(['true', 'false', 'null']);

function checkEntry(key, value, line, seen) {
  if (typeof key !== 'string' || !keyPattern.test(key) || reserved.has(key))
    fail('E_KEY', line, 'expected a non-reserved lowercase identifier');
  if (seen.has(key)) fail('E_DUPLICATE', line, 'duplicate mapping key');
  seen.add(key);
  if (typeof value !== 'string' || !/^[\x20-\x26\x28-\x7e]*$/.test(value))
    fail('E_STRING', line, 'expected printable ASCII without apostrophes');
}

export function parse(text, profile = 'M') {
  if (profile !== 'M') throw new TypeError('unknown profile');
  checkText(text);
  const seen = new Set();
  return text.slice(0, -1).split('\n').map((line, index) => {
    const match = /^([^:]*): '(.*)'$/.exec(line);
    if (!match) fail('E_SYNTAX', index + 1, 'expected key: quoted-value');
    const [, key, value] = match;
    checkEntry(key, value, index + 1, seen);
    return [key, value];
  });
}

export function validate(text, profile = 'M') {
  if (profile !== 'M') throw new TypeError('unknown profile');
  parse(text); // Validation and parsing deliberately use the same grammar.
}

export function generate(entries, profile = 'M') {
  if (profile !== 'M') throw new TypeError('unknown profile');
  if (!Array.isArray(entries)) throw new TypeError('expected an array of entries');
  if (entries.length === 0) fail('E_EMPTY', 1, 'expected at least one entry');
  const seen = new Set();
  return Array.from(entries, (entry, index) => {
    if (!Array.isArray(entry) || entry.length !== 2)
      fail('E_SYNTAX', index + 1, 'expected a key/value pair');
    const [key, value] = entry;
    checkEntry(key, value, index + 1, seen);
    return `${key}: '${value}'\n`;
  }).join('');
}

// One-way JSON export: an object in source entry order, every value a string.
export function toJSON(text, profile = 'M') {
  const entries = parse(text, profile);
  return nodesJSON([{ depth: 0, kind: 'map', key: '', value: '' },
    ...entries.map(([key, value]) => ({ depth: 1, kind: 'str', key, value }))]);
}
